def even_odd_palindrome(n: int) -> tuple:
    """
    Given a positive integer n, return a tuple (even_count, odd_count)
    where even_count is the number of integer palindromes in [1, n]
    that are even, and odd_count is the number that are odd.
    """
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    even = 0
    odd = 0
    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                even += 1
            else:
                odd += 1
    return (even, odd)

