def double_the_difference(lst):
    """
    Return the sum of squares of odd integers in the list, ignoring negative numbers and non-integers.
    """
    total = 0
    for x in lst:
        # Check if x is an integer (not a float or other type) and non-negative and odd
        if isinstance(x, int) and x >= 0 and x % 2 == 1:
            total += x * x
    return total

