def solve(s: str) -> str:
    """
    For each character in s:
    - If it's a letter, reverse its case.
    - Otherwise, keep it unchanged.
    If the string contains no letters at all, reverse the entire string.
    """
    # Check if there is at least one letter
    if not any(ch.isalpha() for ch in s):
        return s[::-1]          # reverse the whole string

    # Otherwise, swap case of letters only
    result = []
    for ch in s:
        if ch.isalpha():
            result.append(ch.swapcase())
        else:
            result.append(ch)
    return ''.join(result)
